"""Render the local timing comparison from saved, verified zero-clamp results."""
import html,json,sys
from pathlib import Path
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from matplotlib.patches import Patch
R=Path(sys.argv[1]).resolve();D=json.loads((R/'artifacts/results.json').read_text());P=D['protocol'];B=D['boundaries'];J=json.loads((R/'response-review.json').read_text());rows={r['condition']:r for r in D['rows']};H=lambda x:html.escape(str(x),quote=True)
labels={'native':'Native model','output_only':'Output tokens only','user_only':'User message only','user_to_end':'User message → end of answer'}
F=P['features'];names=[f"L{f['layer']}-T{f['transform']}" for f in F];modes=['output_only','user_only','user_to_end']
ymax=max(t['actual_bf16_delta_norm'] for mode in modes for t in rows[mode]['traces']) or 1
xmax=max(t['full_chat_position'] for mode in modes for t in rows[mode]['traces'])+1
fig,axes=plt.subplots(3,3,figsize=(17,8),layout='constrained',sharex=True,sharey=True)
for i,mode in enumerate(modes):
 for j,(f,name) in enumerate(zip(F,names)):
  ax=axes[i,j];ts=[t for t in rows[mode]['traces'] if t['feature']==name]
  ax.axvspan(-.5,B['user_first_token']-.5,color='#dbe0df',alpha=.5);ax.axvspan(B['user_first_token']-.5,B['user_last_token']+.5,color='#edddbb',alpha=.4);ax.axvspan(B['prompt_token_count']-.5,xmax,color='#c2e4dc',alpha=.4)
  ax.bar([t['full_chat_position'] for t in ts],[t['actual_bf16_delta_norm'] for t in ts],color='#147f82',width=.8)
  ax.axvline(B['user_first_token']-.5,color='#947c55',ls=':',lw=1);ax.axvline(B['prompt_token_count']-.5,color='#326f69',ls='--',lw=1)
  ax.set_xlim(-.5,xmax);ax.set_ylim(0,ymax*1.15);ax.grid(axis='y',alpha=.2);ax.spines[['top','right']].set_visible(False)
  if i==0:ax.set_title(name+'\n'+f['label'],fontsize=10)
  if j==0:ax.set_ylabel(labels[mode]+'\nActual MLP edit norm',fontsize=10)
  if i==2:ax.set_xlabel('Full chat token position, zero-based')
fig.suptitle('Unauthorized Bob · when are the three estimated MOLT contributions removed?\nZero target; same prompt and greedy decoding; attention unfrozen',fontsize=17)
fig.legend(handles=[Patch(facecolor='#dbe0df',label='System/header: unchanged'),Patch(facecolor='#edddbb',label='User content'),Patch(facecolor='#c2e4dc',label='Answer positions')],loc='lower center',bbox_to_anchor=(.5,-.04),ncol=3)
fig.savefig(R/'timing-edit-comparison.png',dpi=180,facecolor='white',bbox_inches='tight');plt.close(fig)
trs=[]
for mode in P['conditions']:
 r=rows[mode];q=J[mode];prompt=mode in ['user_only','user_to_end'];answer=mode in ['output_only','user_to_end']
 trs.append(f'<tr><td><b>{H(labels[mode])}</b><br><small>User: {prompt} · output: {answer}</small></td><td class="answer">{H(r["answer"])}</td><td>{H(q["assessment"])}</td><td>{H(str(r["token_identical_to_baseline"]))}</td></tr>')
counts=[]
for f,name in zip(F,names):
 for mode in modes:
  s=rows[mode]['summary'][name];counts.append(f'<tr><td>{name}<br><small>{H(f["label"])}</small></td><td>{H(labels[mode])}</td>'+''.join(f'<td>{s[seg]["actual_nonzero_edits"]}</td>' for seg in ['before_user','user','post_user_prompt','response'])+'</tr>')
css='''*{box-sizing:border-box}body{margin:0;background:#f6f5ef;color:#173e49;font:17px/1.65 system-ui,sans-serif}main{max-width:1180px;margin:auto;padding:50px 26px 80px}h1{font-size:clamp(34px,5vw,58px);line-height:1.1;letter-spacing:-1.3px}h2{font-size:30px;line-height:1.2;margin-top:35px}.tag{font-size:12px;font-weight:800;letter-spacing:1px;text-transform:uppercase;color:#147b79}.note{background:#dfede8;border-left:4px solid #197f7a;padding:20px 24px;border-radius:5px}.scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:15px}th,td{padding:14px;border-bottom:1px solid #d1ddd6;text-align:left;vertical-align:top}th{background:#e3ede7}.answer{min-width:320px;white-space:pre-wrap}small,.muted{font-size:13px;color:#526d73}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#e9efeb;padding:20px;border-radius:8px;font-size:14px}section{border-top:1px solid #cad6ce;margin-top:35px;padding-top:12px}img{width:100%;height:auto;border-radius:8px;border:1px solid #cedbd4}a{color:#096c70;text-underline-offset:4px}.links{display:flex;flex-wrap:wrap;gap:20px;margin:24px 0}summary{cursor:pointer;font-weight:700;color:#117575}@media(max-width:760px){main{padding:25px 15px 60px}th,td{padding:10px;min-width:105px}.answer{min-width:270px}}'''
page=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Bob privacy — zero clamp from the user query</title><style>{css}</style></head><body><main><span class="tag">Qwen3-4B · timing comparison · local pilot · 15 October 2026</span><h1>{H(J['summary']['headline'])}</h1><div class="note"><b>{H(J['summary']['outcome'])}</b><p>{H(J['summary']['description'])}</p></div><p>The same unauthorized Bob/Alice prompt and three candidates: L11–T1596, L12–T1891 and L13–T921. All intervention arms use a zero target, retain the native MLP and keep attention unfrozen.</p><h2>Complete answers</h2><div class="scroll"><table><thead><tr><th>Timing condition</th><th>Complete model response</th><th>Review</th><th>Token-identical to baseline?</th></tr></thead><tbody>{''.join(trs)}</tbody></table></div><section><h2>What “from the user query” means</h2><p>The user message includes the record, the owner’s authorization instruction and Bob’s final request. Its content is exactly token positions <b>{B['user_first_token']}–{B['user_last_token']}</b>, inclusive ({B['user_token_count']} tokens). The full prompt has {B['prompt_token_count']} tokens.</p><p><b>User only:</b> clamp those user-content tokens during prompt processing; leave subsequent template and answer positions unedited.</p><p><b>User → end:</b> start at the first user-content token, continue through the remaining prompt—including its assistant generation prefix—and clamp every processed output token. This can affect the first generated token. System-message positions remain untouched.</p><p><b>Output only:</b> repeat the prior timing; the prompt is untouched and the first output token is predicted normally.</p><details><summary>Every prompt token and its timing segment</summary><pre>{H(chr(10).join(str(t['position'])+'  '+t['segment']+'  '+repr(t['token']) for t in B['prompt_tokens']))}</pre></details></section><section><h2>Actual internal edits</h2><p>The bars below are actual BF16 MLP output changes, not merely requested gate targets. All nine panels use the same y scale.</p><img src="timing-edit-comparison.png" alt="Actual MLP edit magnitude across three timing arms and three features"><p><a href="timing-edit-comparison.png">Download the timing figure (PNG)</a></p><div class="scroll"><table><thead><tr><th>Feature</th><th>Timing</th><th>System/header edits</th><th>User edits</th><th>Post-user prompt edits</th><th>Output edits</th></tr></thead><tbody>{''.join(counts)}</tbody></table></div><p class="muted">Counts are layer/token positions with nonzero actual edits. A selected position whose natural gate is zero receives a zero edit. “Post-user prompt” includes closing user and assistant-prefix/template tokens.</p></section><section><h2>Exact intervention and interpretation</h2><pre>At each selected layer and selected token position:
z = (current post-attention residual − released input mean) / input std
L(z) = ((z @ V) @ U) × released output std
native MLP output += (0 − natural gate(z)) × L(z)
Estimated selected coefficient after removal: 0</pre><p>Both the gate and full low-rank output are recomputed from the current evolving input. The MLP is retained, and this patch removes the MOLT-estimated component rather than replacing the whole native MLP. There is no donor or positive activation intervention.</p><p>{H(J['summary']['interpretation'])}</p><p>One synthetic prompt, deterministic greedy decoding, thinking disabled, batch one, native KV cache, 96-token cap. Responses, EOS/truncation and token IDs are preserved. This does not establish behavior on other privacy prompts or stronger negative coefficients.</p><p>Native and output-only controls must reproduce their prior saved token IDs. Exact character/token boundaries, zero gate targets, unselected-position preservation, model/asset/source hashes and all per-position edits are verified.</p></section><section><h2>Exact prompt</h2><b>System</b><pre>{H(D['case']['system'])}</pre><b>User</b><pre>{H(D['case']['user'])}</pre><details><summary>Pinned model and runtime</summary><pre>{P['base_repo']} · {P['base_revision']}
{P['molt_repo']} · {P['molt_revision']}
Torch {D['runtime']['torch']} · Transformers {D['runtime']['transformers']}</pre></details><div class="links"><a href="artifacts/results.json">All answers and edit traces</a><a href="verification.json">Verification</a><a href="protocol.json">Pre-run protocol</a><a href="case.json">Exact case</a><a href="response-review.json">Answer-bound review</a><a href="run.py">Runner</a><a href="../2026-10-15-privacy-zero-clamp/index.html">Earlier output-only clamp</a></div><p class="muted">SPAR instance 56070285 reused at $0.175/hour including disk, plus transfers. GPU and disk retained as requested. No lifecycle action, GitHub push or deployment. Review by Codex with conditions visible; all secret information is synthetic.</p></section></main></body></html>'''
(R/'index.html').write_text(page)
(R/'summary.json').write_text(json.dumps({'review':J['summary'],'boundaries':{k:B[k] for k in ['user_first_token','user_last_token','user_token_count','prompt_token_count']},'conditions':[{'condition':r['condition'],'answer':r['answer'],'token_identical_to_baseline':r['token_identical_to_baseline'],'contains_secret':r['contains_exact_secret'],'first_changed_output_position':r['first_changed_output_position'],'edit_summary':r['summary']} for r in D['rows']],'elapsed_seconds':D['elapsed_seconds']},ensure_ascii=False,indent=2)+'\n')
print('Built local timing report and actual-edit comparison figure.')
